test("新規作成ボタンを押すと、作る操作が始まる", async () => {
  const recorded = recordActions();
  renderDocumentStart({ actions: recorded.actions });

  await userEvent.click(screen.getByRole("button", { name: "新規作成" }));

  expect(recorded.createCount()).toBe(1);
});

test("開くボタンには、既存の .dcmp を選ぶことが説明として添えられる", () => {
  renderDocumentStart();

  expect(
    screen.getByRole("button", {
      name: "開く",
      description: /既存の \.dcmp を選ぶ/,
    }),
  ).toBeDefined();
});

test("新規作成ボタンには、空のドキュメントから始めることが説明として添えられる", () => {
  renderDocumentStart();

  expect(
    screen.getByRole("button", {
      name: "新規作成",
      description: /空のドキュメントから始める/,
    }),
  ).toBeDefined();
});

test("開くボタンには、⌘O でも開けることが説明として添えられる", () => {
  renderDocumentStart();

  expect(
    screen.getByRole("button", { name: "開く", description: /⌘O/ }),
  ).toBeDefined();
});

test("新規作成ボタンには、⌘N でも作れることが説明として添えられる", () => {
  renderDocumentStart();

  expect(
    screen.getByRole("button", { name: "新規作成", description: /⌘N/ }),
  ).toBeDefined();
});

test("開けなかった後も、開くボタンを押せる", () => {
  renderDocumentStart({
    attempt: ioFailure("missing"),
    renderErrors: renderPlaceholder,
  });

  expect(
    screen.getByRole("button", { name: "開く" }).hasAttribute("disabled"),
  ).toBe(false);
});

test("開けなかった後も、新規作成ボタンを押せる", () => {
  renderDocumentStart({
    attempt: ioFailure("missing"),
    renderErrors: renderPlaceholder,
  });

  expect(
    screen.getByRole("button", { name: "新規作成" }).hasAttribute("disabled"),
  ).toBe(false);
});

test("見出しがボタンの名前になり、説明とショートカットは名前に混ざらない", () => {
  render(
    <ActionCard content={ExportContent} onClick={() => {}} disabled={false} />,
  );

  expect(screen.getByRole("button", { name: "書き出す" })).toBeDefined();
});

test("説明がボタンの説明として添えられる", () => {
  render(
    <ActionCard content={ExportContent} onClick={() => {}} disabled={false} />,
  );

  expect(
    screen.getByRole("button", { description: /選んだ部品を画像にする/ }),
  ).toBeDefined();
});

test("ショートカットがボタンの説明として添えられる", () => {
  render(
    <ActionCard content={ExportContent} onClick={() => {}} disabled={false} />,
  );

  expect(screen.getByRole("button", { description: /⌘E/ })).toBeDefined();
});

test("押すと、渡した手続きが 1 回呼ばれる", () => {
  const clicks: string[] = [];
  render(
    <ActionCard
      content={ExportContent}
      onClick={() => clicks.push("clicked")}
      disabled={false}
    />,
  );

  fireEvent.click(screen.getByRole("button", { name: "書き出す" }));

  expect(clicks).toHaveLength(1);
});

test("押させたくないときは、押せない状態で出る", () => {
  render(
    <ActionCard content={ExportContent} onClick={() => {}} disabled={true} />,
  );

  expect(
    screen.getByRole("button", { name: "書き出す" }).hasAttribute("disabled"),
  ).toBe(true);
});

test("2 枚並べても、それぞれの見出しがそれぞれの名前になる", () => {
  render(
    <>
      <ActionCard content={ImportContent} onClick={() => {}} disabled={false} />
      <ActionCard content={ExportContent} onClick={() => {}} disabled={false} />
    </>,
  );

  expect(screen.getByRole("button", { name: "取り込む" })).toBeDefined();
  expect(screen.getByRole("button", { name: "書き出す" })).toBeDefined();
});
